<template>
  <section class="medication-review" data-testid="medication-reconciliation-panel" :aria-label="t('title')">
    <header><div><h2>{{t('title')}}</h2><p>{{t('intro')}}</p></div><button type="button" :disabled="state.loading" @click="refresh">{{t('refresh')}}</button></header>
    <p v-if="!patientId">{{t('patient')}}</p>
    <template v-else>
      <p v-if="state.error" role="alert">{{t(state.error)}}</p>
      <ul v-if="state.capabilities?.blockedReasons?.length"><li v-for="reason in state.capabilities.blockedReasons" :key="reason">{{t(reason)}}</li></ul>
      <div v-if="state.capabilities?.read" class="create-controls"><label>{{t('medicine')}}<select v-model="medicine"><option :value="null">{{t('select')}}</option><option v-for="item in state.capabilities.medications" :key="item.id" :value="item.id">{{item.name}}</option></select></label><button v-if="state.capabilities?.create" type="button" :disabled="!medicine || locked" @click="start">{{t('create')}}</button><button v-if="state.capabilities?.recordFacts" type="button" :disabled="!medicine || locked" @click="flow.loadPersonalIntakes(medicine)">{{t('intakeTitle')}}</button></div>
      <div v-if="state.capabilities?.read" class="catalogue-controls"><p>{{t('catalogueHelp')}}</p><button v-if="state.capabilities.medicationCursor" type="button" @click="flow.loadMedications(true)">{{t('moreMedicines')}}</button><button v-if="state.capabilities.doctorCursor" type="button" @click="flow.loadClinicians(true)">{{t('moreClinicians')}}</button></div>
      <p v-if="state.capabilities?.read && !state.items.length">{{t('empty')}}</p>
      <ul class="review-list"><li v-for="item in state.items" :key="item.executionId"><span>{{item.medicationName}} · {{t(item.state || 'DRAFT')}}</span><button type="button" :disabled="locked" @click="open(item.executionId)">{{t('open')}}</button></li></ul><button v-if="state.nextCursor" type="button" @click="flow.loadList(true)">{{t('more')}}</button>
      <section v-if="state.phase==='unknown'" role="status"><p>{{t('unknown')}}</p><button type="button" @click="flow.reconcile">{{t('reconcile')}}</button><button type="button" @click="flow.retry">{{t('retry')}}</button></section>
      <section v-if="state.phase==='invalid'" role="status"><p>{{t('invalid')}}</p><button type="button" @click="flow.editAfterError">{{t('edit')}}</button></section>
      <section v-if="state.phase==='conflict'" role="status"><p>{{t('conflict')}}</p><template v-if="state.error==='EXECUTION_EXISTS' && state.draft"><button type="button" @click="flow.reviewWinner">{{t('reviewWinner')}}</button><button v-if="state.reviewedWinner && state.factIntake" type="button" @click="flow.useFactWinner">{{t('reviewCurrentFact')}}</button><button v-if="state.reviewedWinner && !state.factIntake" type="button" @click="flow.newReconciliation">{{t('adopt')}}</button></template><button v-else type="button" @click="refreshDecision">{{t('edit')}}</button></section>
      <ReconciliationDetail v-if="state.detail" :detail="state.detail" :doctors="state.capabilities?.eligibleDoctors || []" :disabled="locked" @command="command"/>
      <ReplacementPreview v-if="state.replacementPreview" :preview="state.replacementPreview" :disabled="locked || ['invalid','conflict'].includes(state.phase)" @submit="schedule" @close="state.replacementPreview=null"/>
      <IntakeFollowUpPanel v-if="state.detail || state.personalMedication" :items="state.intakes" :next-cursor="state.intakeCursor" :disabled="locked" @command="flow.openFact" @more="state.detail ? flow.loadIntakes(true) : flow.loadPersonalIntakes(state.personalMedication,true)"/>
      <IntakeFactDialog v-if="state.dialog && state.factIntake && state.draft" :draft="state.draft" :operation="state.operation" :intake="state.factIntake" :disabled="locked || ['invalid','conflict'].includes(state.phase)" @submit="submitFact" @close="flow.close"/>
      <ReconciliationDialog v-if="state.dialog && !state.factIntake && state.draft && state.operation!=='SCHEDULE_REPLACEMENT'" :draft="state.draft" :operation="state.operation" :doctors="state.capabilities?.eligibleDoctors || []" :sources="state.sources" :disabled="locked || ['invalid','conflict'].includes(state.phase)" @submit="flow.submit" @close="flow.close"/>
      <button v-if="state.dialog && state.sourceCursor" type="button" @click="flow.loadSources(true)">{{t('more')}} · {{t('source')}}</button>
      <section v-if="state.detail" class="review-history"><h3>{{t('history')}}</h3><button type="button" @click="flow.loadEvents()">{{t('refresh')}}</button><ol><li v-for="event in state.events" :key="event.id">{{t(event.type)}} · {{event.occurredAt}} · #{{event.actorId}}</li></ol><button v-if="state.eventCursor" type="button" @click="flow.loadEvents(true)">{{t('more')}}</button></section>
      <section v-if="state.detail" class="review-deliveries"><h3>{{t('notifications')}}</h3><p>{{t('notificationHelp')}}</p><button type="button" @click="flow.loadDeliveries()">{{t('refresh')}}</button><p v-if="['unknown','conflict'].includes(state.deliveryPhase)" role="status">{{t('deliveryConflict')}}</p><article v-for="row in state.deliveries" :key="row.id"><p>#{{row.id}} · {{t(row.status)}}</p><label v-if="row.requiresDuplicateRiskAcknowledgement" class="risk"><input v-model="risk[row.id]" type="checkbox"/>{{t('duplicate')}}</label><button v-if="row.canRetry" type="button" :disabled="state.deliveryPhase==='submitting' || (row.requiresDuplicateRiskAcknowledgement && !risk[row.id])" @click="flow.retryDelivery(row,!!risk[row.id])">{{t('deliveryRetry')}}</button></article><button v-if="state.deliveryCursor" type="button" @click="flow.loadDeliveries(true)">{{t('more')}}</button></section>
    </template>
  </section>
</template>
<script setup>
import {computed,reactive,ref,toRef,watch} from 'vue';
import {useMedicationExecution} from '@/composables/useMedicationExecution';
import {medicationText as t} from '@/utils/medicationExecutionCopy';
import ReconciliationDetail from './ReconciliationDetail.vue';
import IntakeFactDialog from './IntakeFactDialog.vue';
import IntakeFollowUpPanel from './IntakeFollowUpPanel.vue';
import ReplacementPreview from './ReplacementPreview.vue';
import ReconciliationDialog from './ReconciliationDialog.vue';
const props=defineProps({patientId:{type:Number,default:null},executionId:{type:Number,default:null},navigationKey:{type:String,default:''}});
const flow=useMedicationExecution(toRef(props,'patientId')),state=flow.state,medicine=ref(null),risk=reactive({});
const locked=computed(()=>['submitting','unknown'].includes(state.phase));
function draft(){return {medicationId:medicine.value,selectedVerifierId:null,source:{kind:'MANUAL',provenance:''},mapping:{action:'CHANGE',quantity:'',unit:'',times:[],weekdays:[],scheduleZone:'',effectiveLocal:'',effectiveOffsetSeconds:'',effectiveAt:''}};}
async function refresh(){if(props.executionId){await flow.open(props.executionId);if(state.error==='PATIENT_MISMATCH')return;}await flow.load();if(state.detail)await flow.loadIntakes();}
async function open(id){await flow.open(id);if(state.detail){await flow.loadEvents();await flow.loadDeliveries();await flow.loadIntakes();}}
async function start(){const item=state.capabilities.medications.find(m=>m.id===medicine.value);if(item?.executionId){await open(item.executionId);return;}else flow.openDraft('CREATE_RECONCILIATION',draft());await flow.loadSources();}
async function schedule(body){if(flow.openDraft('SCHEDULE_REPLACEMENT',body))await flow.submit();}
async function command(operation){const d=state.detail;if(!d)return;if(operation==='SCHEDULE_REPLACEMENT'){await flow.loadReplacementPreview();return;}if(operation==='CANCEL_SCHEDULE'){flow.openDraft(operation,{reconciliationId:d.reconciliation.id,reason:''});return;}if(operation==='NEW_RECONCILIATION'){medicine.value=d.medicationId;flow.openDraft(operation,draft());await flow.loadSources();return;}if(operation==='REVISE_RECONCILIATION'){const source=d.revision.source;flow.openDraft(operation,{reconciliationId:d.reconciliation.id,selectedVerifierId:d.reconciliation.selectedVerifierId,source:source.kind==='MANUAL'?{kind:'MANUAL',provenance:source.provenance}:{kind:'PRESCRIPTION',prescriptionId:source.prescriptionId,itemId:source.itemId,version:source.version},mapping:d.revision.mapping});await flow.loadSources();return;}const body={reconciliationId:d.reconciliation.id,revisionId:d.revision.id,revisionHash:d.revision.revisionHash};if(operation!=='VERIFY_RECONCILIATION')body.reason='';flow.openDraft(operation,body);}
async function submitFact(body){state.draft=body;await flow.submit();}
async function refreshDecision(){const id=state.detail?.executionId;if(state.factIntake){flow.close();if(id)await open(id);return;}if(id)await flow.open(id,true);flow.editAfterError();}
watch(()=>[props.patientId,props.executionId,props.navigationKey],()=>{flow.invalidate();medicine.value=null;for(const key of Object.keys(risk))delete risk[key];refresh();},{immediate:true,flush:'sync'});
</script>
<style scoped>
.medication-review{margin:20px 0;padding:20px;border:1px solid var(--line);border-radius:16px;background:var(--paper);color:var(--ink-950);min-width:0;overflow-wrap:anywhere}.medication-review header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;flex-wrap:wrap}.medication-review h2{margin:0}.medication-review p{line-height:1.6}.medication-review button,.medication-review select{font:inherit;min-height:44px;padding:8px 12px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink-950);max-width:100%;white-space:normal}.medication-review button{cursor:pointer}.medication-review button:disabled{opacity:.55;cursor:default}.medication-review button:focus-visible,.medication-review select:focus-visible{outline:3px solid var(--care-600);outline-offset:2px}.create-controls{display:flex;align-items:end;flex-wrap:wrap;gap:12px}.create-controls label{display:flex;flex-direction:column;gap:5px;min-width:0}.create-controls select{min-width:min(260px,100%)}.review-list{padding:0;list-style:none}.review-list li{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px 0;min-width:0}.review-history,.review-deliveries{margin-top:16px;border-top:1px solid var(--line);padding-top:12px}.review-deliveries article{border-bottom:1px solid var(--line);padding:12px 0}.risk{display:flex;gap:8px;align-items:center;min-height:44px}.risk input{width:22px;height:22px;flex-shrink:0}.medication-review :deep(.reconciliation-editor),.medication-review :deep(.review-detail){margin-top:16px}@media(max-width:600px){.medication-review{padding:12px}.create-controls{align-items:stretch;flex-direction:column}.review-list li{align-items:stretch;flex-direction:column}.medication-review button{width:100%}.risk{align-items:flex-start}}
</style>
